/**
 * Builds responsive variants of the site's raster images and writes
 * src/lib/image-manifest.ts describing them.
 *
 * Static export forces `images.unoptimized`, so Next cannot resize anything.
 * Before this, a 288px-tall gallery card downloaded the full 1024x1536 JPEG
 * (230-350 KB), the 44px navbar logo was a 110 KB JPEG, and nothing was
 * served as AVIF or WebP.
 *
 * For each source image this writes AVIF and WebP copies at a few widths into
 * public/_img/ (gitignored, regenerated by `prebuild`), and records intrinsic
 * dimensions so pages reserve space and do not reflow. Unchanged images are
 * skipped, so repeat runs in development are fast.
 */

import { existsSync, mkdirSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { availableParallelism } from "node:os";
import { dirname, join, parse } from "node:path";

import sharp from "sharp";

const PUBLIC = "public";
const OUT_DIR = join(PUBLIC, "_img");
const OUTPUT = "src/lib/image-manifest.ts";

/** Widths by role. Never upscaled: widths above the original are dropped. */
const POSTER_WIDTHS = [480, 960, 1600];
const PORTRAIT_WIDTHS = [400, 800];
const LOGO_WIDTHS = [96, 192];

const FORMATS = [
  // effort 2: a few percent larger than the default 4, roughly 3x faster to
  // encode — this runs on every CI build.
  { ext: "avif", options: { quality: 55, effort: 2 } },
  { ext: "webp", options: { quality: 78 } },
];

function listJpegs(dir) {
  return readdirSync(join(PUBLIC, dir))
    .filter((file) => /\.jpe?g$/i.test(file))
    .sort()
    .map((file) => `/${dir}/${file}`);
}

const sources = [
  ...listJpegs("infographics").map((src) => ({ src, widths: POSTER_WIDTHS })),
  ...listJpegs("comics").map((src) => ({ src, widths: POSTER_WIDTHS })),
  ...["/founder-pic.jpeg", "/Team_mate_1.jpeg", "/Team_mate_2.jpeg", "/Sponser-1.jpeg"]
    .filter((src) => existsSync(join(PUBLIC, src)))
    .map((src) => ({ src, widths: PORTRAIT_WIDTHS })),
  { src: "/Site_logo.jpeg", widths: LOGO_WIDTHS },
];

function isFresh(target, sourceMtime) {
  return existsSync(target) && statSync(target).mtimeMs >= sourceMtime;
}

const entries = [];
const jobs = [];
let written = 0;

for (const { src, widths } of sources) {
  const input = join(PUBLIC, src);
  const sourceMtime = statSync(input).mtimeMs;
  const { width, height } = await sharp(input).metadata();

  if (!width || !height) {
    console.warn(`Could not read dimensions for ${src} — skipping.`);
    continue;
  }

  const { dir, name } = parse(src);
  const folder = dir === "/" ? "" : dir;
  const usable = widths.filter((w) => w < width);
  // Always include the original width as the largest candidate.
  const targets = [...usable, width];
  const variants = {};

  for (const { ext, options } of FORMATS) {
    variants[ext] = [];

    for (const target of targets) {
      const publicPath = `/_img${folder}/${name}-${target}.${ext}`;
      const file = join(PUBLIC, publicPath);

      if (!isFresh(file, sourceMtime)) {
        jobs.push(async () => {
          mkdirSync(dirname(file), { recursive: true });
          await sharp(input).rotate().resize({ width: target }).toFormat(ext, options).toFile(file);
          written += 1;
        });
      }

      variants[ext].push({ width: target, src: publicPath });
    }
  }

  entries.push([src, { width, height, variants }]);
}

// AVIF encoding is mostly single-threaded per image, so run several at once.
sharp.concurrency(1);
const pool = Math.max(1, availableParallelism());
const queue = [...jobs];
await Promise.all(
  Array.from({ length: pool }, async () => {
    while (queue.length > 0) await queue.shift()();
  }),
);

const body = entries.map(([src, data]) => `  ${JSON.stringify(src)}: ${JSON.stringify(data)},`).join("\n");

writeFileSync(
  OUTPUT,
  `// Generated by scripts/generate-image-manifest.mjs — do not edit by hand.

export type ImageVariant = { width: number; src: string };

export type ImageEntry = {
  width: number;
  height: number;
  variants: { avif: ImageVariant[]; webp: ImageVariant[] };
};

export const imageManifest: Record<string, ImageEntry> = {
${body}
};

export function getImageDimensions(src: string) {
  const entry = imageManifest[src];
  return entry ? { width: entry.width, height: entry.height } : null;
}

export function getImageEntry(src: string) {
  return imageManifest[src] ?? null;
}
`,
  "utf8",
);

console.log(`Wrote ${OUTPUT} with ${entries.length} images (${written} variant files generated in ${OUT_DIR}).`);
